'use client';

import Image from 'next/image';

interface ProductCardProps {
  product: {
    id: number;
    name: string;
    price: number;
    thumbnail: string;
    category?: { name: string };
  };
}

export default function ProductCard({ product }: ProductCardProps) {
  const formattedPrice = new Intl.NumberFormat('vi-VN').format(product.price);

  return (
    <div className="rounded-lg border overflow-hidden hover:shadow-lg transition-shadow cursor-pointer">
      <div className="relative h-48 bg-gray-100">
        {product.thumbnail ? (
          <Image
            src={product.thumbnail}
            alt={product.name}
            fill
            className="object-cover"
          />
        ) : (
          <div className="flex items-center justify-center h-full text-gray-400">
            No Image
          </div>
        )}
      </div>
      <div className="p-4">
        <p className="text-xs text-gray-500">{product.category?.name}</p>
        <h3 className="font-medium text-sm line-clamp-2 mt-1">{product.name}</h3>
        <p className="text-red-600 font-semibold mt-2">{formattedPrice}đ</p>
      </div>
    </div>
  );
}
